using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace Stackshot
{
    static class CaptureEditingTests
    {
        sealed class Input:Canvas{internal Input(Bitmap image):base(image){ModifierSource=delegate{return Keys.None;};}internal void Drag(PointF a,PointF b){var p=ImageToControl(a);var q=ImageToControl(b);OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,q.X,q.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,q.X,q.Y,0));}}
        static System.Collections.Generic.IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in Children(c))yield return child;}}
        static Bitmap Source(int w=1000,int h=700){var image=new Bitmap(w,h);using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(42,58,76));using(var p=new Pen(Color.FromArgb(80,100,120)))for(int x=20;x<w;x+=32)g.DrawLine(p,x,0,x,h);}return image;}
        static CaptureOverlay Overlay(){return new CaptureOverlay(Source(),new Rectangle(0,0,1000,700),new Rectangle(100,70,700,420),new[]{new Rectangle(0,0,1000,680)});}
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        static string Hash(Bitmap image){using(var stream=new MemoryStream()){image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(stream.ToArray()));}}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("capture scene/cached mask moving range erases old positions without moving canvas HWND",delegate{using(var overlay=Overlay()){var canvas=overlay.AnnotationCanvas;var bounds=canvas.Bounds;var handle=canvas.Handle;check(canvas.FullCaptureSurface&&!Children(overlay).Any(c=>(c.AccessibleName??"").StartsWith("选区控制点")),"moving child HWND handles remain");using(var dirty=new Bitmap(1000,700))using(var g=Graphics.FromImage(dirty))using(var scene=new CaptureScene(canvas.Img,70)){for(int i=0;i<80;i++){var range=new Rectangle(10+i*3,20+i*2,450,300);canvas.SetCaptureSelection(range,false);scene.Paint(g,range);using(var fresh=new Bitmap(1000,700)){using(var fg=Graphics.FromImage(fresh))scene.Paint(fg,range);check(Hash(dirty)==Hash(fresh),"old frame pixels survived");}check(canvas.Bounds==bounds&&canvas.Handle==handle,"canvas moved or recreated");}}check(!overlay.Visible,"scene test showed overlay");}});
            run("capture scene/offscreen cached painting benchmark reports thirty samples",delegate{using(var source=Source(1920,1080)){var timer=Stopwatch.StartNew();using(var scene=new CaptureScene(source,70))using(var target=new Bitmap(1920,1080))using(var g=Graphics.FromImage(target)){long init=timer.ElapsedMilliseconds;var samples=new double[30];for(int i=0;i<30;i++){timer.Restart();scene.Paint(g,new Rectangle(100+i*5,100+i*3,1000,600));samples[i]=timer.Elapsed.TotalMilliseconds;}Array.Sort(samples);File.WriteAllText(Path.Combine(output,"capture-scene-benchmark.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{Method="synthetic 1920x1080 cached raster paint only; no real capture latency",Samples=30,CacheInitMs=init,MedianMs=samples[15],P95Ms=samples[28],WorstMs=samples[29],GuiStatus="NOT RUN"}));check(samples.All(s=>s<1000),"synthetic repaint stalled for over a second");}}});
            run("capture scene/native canvas repaint keeps one cache and overwrites dirty pixels after moves",delegate{using(var overlay=Overlay()){var c=overlay.AnnotationCanvas;for(int i=0;i<20;i++){c.SetCaptureSelection(new Rectangle(20+i*8,20+i*6,500,320),false);using(var a=UiPaintingTests.NativePaint(c,Color.Magenta))using(var b=UiPaintingTests.NativePaint(c,Color.Lime)){check(Hash(a)==Hash(b),"native scene depends on previous pixels");if(i==19)a.Save(Path.Combine(output,"capture-scene-native-final.png"));}}check(c.SceneBuildCount==1,"dim layer rebuilt during crop moves");check(!overlay.Visible,"native repaint showed overlay");}});
            run("capture style/radius slider updates selected rounded rectangle with arbitrary radius",delegate{using(var overlay=Overlay()){var c=overlay.AnnotationCanvas;var s=ScreenCraftTests.Mark(Tool.Rect,150,120,450,350);s.CornerRadius=12;c.AddAnnotation(s);var slider=Children(overlay).OfType<CaptureSlider>().Single(x=>x.AccessibleName=="圆角半径快捷调整");slider.Value=57;check(c.SelectedShape.CornerRadius==57,"radius preset still fixed at twelve");using(var image=c.Render())image.Save(Path.Combine(output,"arbitrary-radius-offscreen.png"));}});
            run("text/live plain text edits font foreground and background without committing or losing content",delegate{using(var c=new Canvas(Source())){var s=ScreenCraftTests.Mark(Tool.Text,100,100,100,100);s.Text="before";c.AddAnnotation(s);c.EditNote();var box=c.Controls.OfType<TextBox>().Single();box.Text="建筑 after";c.SetTextSize(48);c.ApplyTextPreset(true);check(c.Typing&&Math.Abs(box.Font.Size-48)<1&&box.Text=="建筑 after"&&box.ForeColor.ToArgb()==Color.White.ToArgb(),"live controls blocked or text lost");typeof(Control).GetMethod("OnLostFocus",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(box,new object[]{EventArgs.Empty});check(c.Typing,"style focus ended edit");c.CommitText();check(c.SelectedShape.Text=="建筑 after"&&c.SelectedShape.FillEnabled&&c.SelectedShape.FontPx==48,"live text not persisted");}});
            run("notes/fixed white glyphs and accent background keep typography separate from marker size",delegate{using(var c=new Canvas(Source())){c.SetTool(Tool.Counter);var markerSize=c.DefaultStyle.MarkerSize;c.ApplyTextPreset(true);c.SetTextSize(36);c.SetTextColor(Color.Teal);check(c.Color.ToArgb()==Color.Teal.ToArgb()&&c.DefaultStyle.MarkerSize==markerSize&&c.DefaultStyle.NoteFontPx==36&&c.ActiveTextColor.ToArgb()==Color.White.ToArgb(),"one-color label defaults broken");var s=ScreenCraftTests.Mark(Tool.Counter,100,130,100,130);s.Color=Color.Teal;s.Text="建筑";s.NoteOffset=new PointF(80,-20);s.NoteWidth=240;c.AddAnnotation(s);var box=Painter.NoteBounds(c.SelectedShape);using(var filled=c.Render()){filled.Save(Path.Combine(output,"note-color-presets-offscreen.png"));check(filled.GetPixel((int)box.Right-8,(int)box.Top+10).ToArgb()==Color.Teal.ToArgb(),"note background is not annotation color");}c.ApplyTextPreset(false);c.SetTextSize(36);check(Painter.NoteInk(c.SelectedShape).ToArgb()==Color.White.ToArgb()&&c.SelectedShape.FontPx==s.FontPx&&c.SelectedShape.NoteFontPx==36,"legacy preset changed fixed white glyphs or marker size");}});
            run("notes/live callout font remains adjustable and no default white editor fill",delegate{using(var c=new Canvas(Source())){var s=ScreenCraftTests.Mark(Tool.Counter,100,130,100,130);s.Text="original";s.NoteOffset=new PointF(80,-20);c.AddAnnotation(s);c.EditNote();var box=c.Controls.OfType<TextBox>().Single();box.Text="说明可继续输入";c.SetTextSize(52);c.SetTextColor(Color.Yellow);check(c.Typing&&box.Font.Size==52&&box.ForeColor.ToArgb()==Color.White.ToArgb()&&box.BackColor.ToArgb()==Color.Yellow.ToArgb(),"callout editor did not update");c.CommitText();check(c.SelectedShape.NoteFontPx==52&&c.SelectedShape.FontPx==s.FontPx&&c.SelectedShape.Text=="说明可继续输入","callout edit changed circle or dropped text");}});
            run("notes/production drag moves note and anchor independently and undo restores",delegate{using(var owner=new Form{ClientSize=new Size(1000,700)})using(var c=new Input(Source())){owner.Controls.Add(c);c.Bounds=owner.ClientRectangle;var s=ScreenCraftTests.Mark(Tool.Counter,150,170,150,170);s.Text="separate note";s.NoteOffset=new PointF(120,20);c.AddAnnotation(s);var before=c.SelectedShape.A;var box=Painter.NoteBounds(c.SelectedShape);c.Drag(new PointF(box.Left+30,box.Top+15),new PointF(box.Left+70,box.Top+45));check(c.SelectedShape.A==before&&Math.Abs(c.SelectedShape.NoteOffset.X-160)<2,"note drag moved anchor");var note=Painter.NoteBounds(c.SelectedShape).Location;c.Drag(before,new PointF(before.X+45,before.Y+30));check(c.SelectedShape.A.X>before.X+40&&Math.Abs(Painter.NoteBounds(c.SelectedShape).X-note.X)<2&&Math.Abs(Painter.NoteBounds(c.SelectedShape).Y-note.Y)<2,"anchor drag moved note");c.Undo();check(c.AnnotationSnapshot.Single().A==before,"anchor undo");check(!owner.Visible,"drag test showed window");}});
            run("notes/editable project roundtrip preserves independent note typography and fill",delegate{using(var c=new Canvas(Source())){var s=ScreenCraftTests.Mark(Tool.Counter,150,170,150,170);s.Text="saved";s.NoteOffset=new PointF(120,20);s.HasNoteTextColor=true;s.NoteTextColor=Color.White;s.NoteFontPx=46;s.FillEnabled=true;s.FillColor=Color.Red;c.AddAnnotation(s);using(var doc=c.ExportDocument()){string path=Path.Combine(output,"note-styles.sccraft");doc.Save(path);using(var opened=AnnotationDocument.Open(path))using(var a=doc.Render())using(var b=opened.Render()){check(Hash(a)==Hash(b)&&opened.Shapes[0].NoteFontPx==46&&opened.Shapes[0].HasNoteTextColor,"note fields or pixels lost");}}}});
            run("inspector/redesigned controls retain precise radius and live text and separate color roles",delegate{using(var overlay=Overlay()){check(!Children(overlay).OfType<AnnotationInspector>().Any(),"eager inspector startup cost");Click(Children(overlay).OfType<Button>().Single(b=>b.AccessibleName=="详细标注属性"));var inspector=Children(overlay).OfType<AnnotationInspector>().Single();check(!Children(inspector).OfType<ComboBox>().Any()&&Children(inspector).OfType<InspectorColorButton>().Count()==1,"inspector must expose exactly one annotation color");using(var preview=new Bitmap(inspector.Width,Math.Min(1000,inspector.Height))){using(var g=Graphics.FromImage(preview))PreferencesPreview.Draw(g,inspector,inspector);preview.Save(Path.Combine(output,"annotation-inspector-offscreen.png"));}check(!overlay.Visible,"inspector shown");}});
        }
    }
}
